<div class="grid grid-3"><?php foreach($sites as $site):?><a class="card" href="<?=url('/dashboard?website_id='.$site['id'])?>"><span class="feature-icon">◎</span><h3><?=e($site['name'])?></h3><p class="small"><?=e($site['domain'])?></p><div class="row between"><span class="badge"><?=e($site['country'])?></span><span>Open project ↗</span></div></a><?php endforeach;?></div><div class="card stack" id="create"><h2>Add a website</h2><p>Connect a public domain. Crawling starts only when you request an audit.</p><form data-api="website"><div class="form-grid"><?php field('name','Website name');field('domain','Website URL','url','https://');field('country','Country','text','India');field('language','Language','text','en');select_field('search_engine','Search engine',['google'=>'Google','bing'=>'Bing']);field('timezone','Timezone','text','Asia/Kolkata');?></div><button class="button">+ Add website</button></form></div>
